// 1. Security Check: Verify Webhook Secret if set
const incomingSecret = $input.item.json.headers['x-webhook-secret'] || $input.item.json.headers['X-Webhook-Secret'];
const expectedSecret = $env.N8N_WEBHOOK_SECRET;

if (expectedSecret && incomingSecret !== expectedSecret) {
  throw new Error('Unauthorized: Invalid or missing X-Webhook-Secret header');
}

// 2. Extract Body Payload
const body = $input.item.json.body || $input.item.json;
const visitor = body.visitor || {};
const content = body.content || {};
const metadata = body.metadata || {};

if (!visitor.name || !visitor.email || !content.message) {
  throw new Error('Bad Request: Incomplete submission data');
}

// 3. Construct WhatsApp Message Payload
// Supports standard Meta Cloud API freeform or pre-approved utility template
const recipientPhone = $env.OWNER_WHATSAPP_NUMBER || '6281234567890';
const formattedText = `*New Portfolio Contact*\n\n*Visitor:* ${visitor.name}\n*Email:* ${visitor.email}\n*Subject:* ${content.subject || 'Portfolio Inquiry'}\n*Time:* ${metadata.submittedAtFormatted || new Date().toISOString()}\n\n*Message:*\n${content.message}`;

return {
  recipientPhone,
  visitor,
  content,
  metadata,
  formattedText,
  whatsAppPayload: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: recipientPhone.replace(/\D/g, ''),
    type: 'text',
    text: {
      preview_url: false,
      body: formattedText
    }
  }
};
